"use client";

import { useState } from "react";
import VegFilter from "../../../components/menu/VegFilter";
import CategoryTabs from "../../../components/menu/CategoryTabs";
import { Restaurant } from "../../../data/types";

type MenuClientProps = {
  restaurant: Restaurant;
};

export default function MenuClient({ restaurant }: MenuClientProps) {
  const [filter, setFilter] = useState<
    "all" | "veg" | "nonveg"
  >("all");

  // ✅ FILTER PRODUCTS FIRST
  const visibleCategories = restaurant.categories
    .map(cat => {
      const products = cat.products.filter(item =>
        filter === "all" ||
        (filter === "veg" && item.veg) ||
        (filter === "nonveg" && !item.veg)
      );

      return { ...cat, products };
    })
    .filter(cat => cat.products.length > 0);

  return (
    <div className="min-h-screen">
      {/* Header */}
      <div className="p-4">
        <h1 className="text-xl font-bold">{restaurant.name}</h1>

        {restaurant.pure_veg && (
          <div className="text-green-600 mt-1">
            🟢 Pure Veg
          </div>
        )}

        <VegFilter value={filter} onChange={setFilter} />
      </div>

      {/* ✅ PASS FILTERED CATEGORIES ONLY */}
      <CategoryTabs
        categories={visibleCategories.map(cat => ({
          id: cat.id,
          name: cat.name,
        }))}
      />

      {/* Menu */}
      <div className="px-4 pb-10">
        {visibleCategories.map(cat => (
          <section
            key={cat.id}
            id={cat.id}        // ✅ MUST MATCH TAB ID
            className="mt-6 scroll-mt-24"
          >
            <h2 className="text-lg font-semibold mb-2">
              {cat.name}
            </h2>

            {cat.products.map(item => (
              <div
                key={item.id}
                className="border-b py-3 flex justify-between"
              >
                <div>
                  <div className="font-medium">
                    {item.veg ? "🟢" : "🔴"} {item.name}
                  </div>

                  {!item.available && (
                    <div className="text-xs text-red-500">
                      Sold Out
                    </div>
                  )}
                </div>

                <div className="text-right text-sm">
                  {item.sizes.map(s => (
                    <div key={s.id}>
                      {s.size_label} ₹{s.price}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </section>
        ))}
      </div>
    </div>
  );
}
